function Somme() {
  const [a, setA] = useState("");
  const [b, setB] = useState("");
  const [result, setResult] = useState(null);

  const Calcul = () => {
    const sum = Number(a) + Number(b);
    setResult(sum);
  };

  const color = result !== null ? (result > 100 ? "red" : "green") : "black";

  return (
    <div >
      <h2>Calcul de la somme</h2>

      <div >
        <input
          type="number"
          placeholder="Valeur A"
          value={a}
          onChange={(e) => setA(e.target.value)}
          style={{ marginRight: "10px", padding: "5px" }}
        />
        <input
          type="number"
          placeholder="Valeur B"
          value={b}
          onChange={(e) => setB(e.target.value)}
          style={{ padding: "5px" }}
        />
      </div>

      <button onClick={Calcul} style={{ padding: "5px 15px" }}>
        +
      </button>

      {result !== null && (
        <p style={{ color, marginTop: "20px", fontWeight: "bold" }}>
          Résultat : {result}
        </p>
      )}
    </div>
    
  );
}
  const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<Somme />);
